// CSD_RATIONALE_BEGIN
// Root-cause fix for attempt 31's 8 `final_span_unclosed` failures:
// Phase 1 was ignoring all "<<" tokens during free generation.
// The model naturally writes <<int(expr)>> and then, continuing free generation,
// opens another "<<" that never closes. Phase 2 then adds a *third* "<<", compounding
// the confusion and leaving the last span unclosed when budget runs out.
//
// Fix: Phase 1 now checks RenderedEndsWith(generated, "<<") after every appended token.
// When "<<" is detected, we enter constrained mode and BREAK immediately — Phase 1
// stops before the model can open a second "<<". Phase 2 then calls CloseSpanWithinBudget
// with the full remaining budget to generate int(expr)>> at that exact opening.
//
// By stopping at the FIRST "<<" we also benefit accuracy: the model's first <<int(expr)>>
// typically uses correct variable names (n_1, n_2), while any second span it might write
// drifts to wrong forms (n1, n2). Stopping early picks the better span.
//
// Phase 0: Close any inherited open span (small budget).
// Phase 1: Unconstrained generation with "<<" detection; break immediately on detection.
// Phase 2: If inside constrained span, CloseSpanWithinBudget with full remaining budget.
// Phase 3: If no span appeared in Phase 1, force-open one and CloseSpanWithinBudget.
//
// Guidance explicitly forbids curly braces (e.g. {n_1}) in expressions and enforces
// exact variable-name spelling (n_1 not n1) to eliminate `final_span_invalid` failures.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Phase 0 (CloseSpanWithinBudget): Its postcondition guarantees
//     insideOut ==> parser.IsValidPrefix(currentOut), preserving the invariant.
//
//   Phase 1 loop runs only while !insideConstrainedOut, so the antecedent is false
//   throughout each iteration body. When RenderedEndsWith detects "<<", we set
//   currentConstrainedOut := [] and insideConstrainedOut := true. The requires clause
//   gives parser.IsValidPrefix([]), so the invariant holds. The loop then exits because
//   its guard !insideConstrainedOut becomes false.
//
//   Phase 2 (CloseSpanWithinBudget): Postcondition directly guarantees
//     insideOut ==> parser.IsValidPrefix(currentOut).
//
//   Phase 3: OpenConstrainedSpan postcondition gives insideOut := true and
//     currentOut := [], with parser.IsValidPrefix([]) by requires. Then
//     CloseSpanWithinBudget postcondition preserves the invariant.
//
// Invariant 2: progress
//   |generated| <= |generatedPrefix| + steps
//
//   Initialization: generated = generatedPrefix, steps = 0; equality holds.
//
//   Phase 0: CloseSpanWithinBudget appends at most budget0 tokens to generated and
//     we add budget0 to steps, preserving the bound.
//
//   Phase 1 loop: Each iteration increments steps by 1. A non-EOS token appends exactly
//     one token to generated (delta steps = delta generated = 1). EOS breaks without
//     appending (generated unchanged, steps grows by 1). Both branches preserve the
//     bound. Entering constrained mode does not append any token (only sets flags).
//
//   Phase 2: CloseSpanWithinBudget appends at most budget2 = maxSteps - steps_before
//     tokens; we then set steps := maxSteps. So |generated| <= |generatedPrefix| +
//     steps_before + budget2 = |generatedPrefix| + maxSteps = |generatedPrefix| + steps.
//     EOS or rejected suffix tokens inside CloseSpanWithinBudget count against the budget
//     but do not appear in visible output, so the visible growth is at most the budget.
//
//   Phase 3: OpenConstrainedSpan appends 1 token and steps grows by 1. Then
//     CloseSpanWithinBudget appends at most budget3 = maxSteps - steps_before tokens and
//     steps is set to maxSteps. Combined: |generated| <= |generatedPrefix| + maxSteps.
// CSD_PROOF_SKETCH_END

  generated := generatedPrefix;
  insideConstrainedOut := insideConstrained;
  currentConstrainedOut := currentConstrained;
  cost := 0;

  helpers.AppendTaskGuidance(lm,
    "Solve this math problem step by step, showing all work in plain text. " +
    "At the very end of your response, write the answer EXACTLY ONCE in this format: <<int(expr)>> " +
    "STRICT RULES for expr: " +
    "(1) NO curly braces {} anywhere — write n_1 not {n_1}, write initial_amount not {initial_amount}. " +
    "(2) Use EXACTLY the variable names as written in the problem (preserve underscores: n_1 not n1, unit_price not unit price). " +
    "(3) Allowed symbols only: variable names, integers, +, -, *, /, //, %, (, ), int(). " +
    "(4) NO ** operator — you cannot write x**y. " +
    "(5) NO LaTeX (no \\frac, no ^, no \\times). " +
    "(6) Always wrap the final expression in int(). " +
    "(7) Write ONLY ONE <<int(expr)>> block and put it at the very end. Do NOT write << anywhere else. " +
    "Correct example: <<int(n_1 * price - n_2 * discount)>> " +
    "Wrong example: <<int({n_1} * {price} - {n_2} * {discount})>>");

  var steps: nat := 0;

  // Phase 0: Close any inherited open constrained span with a small budget
  if insideConstrainedOut && steps < maxSteps {
    var budget0: nat := 20;
    if budget0 > maxSteps - steps {
      budget0 := maxSteps - steps;
    }
    var cg0, ci0, cc0 := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, budget0
    );
    generated := cg0;
    insideConstrainedOut := ci0;
    currentConstrainedOut := cc0;
    steps := steps + budget0;
  }

  // Phase 1: Free unconstrained generation with "<<" detection.
  // Break immediately when "<<" appears in rendered output.
  while steps < maxSteps && !insideConstrainedOut
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps
  {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      // Enter constrained mode without appending another "<<" (already present)
      insideConstrainedOut := true;
      currentConstrainedOut := [];
      // Loop guard !insideConstrainedOut now false — exits immediately
    }
  }

  // Phase 2: If we entered constrained mode (naturally or from Phase 0 remainder),
  // close the span with the full remaining budget.
  if insideConstrainedOut && steps < maxSteps {
    var budget2: nat := maxSteps - steps;
    var cg2, ci2, cc2 := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, budget2
    );
    generated := cg2;
    insideConstrainedOut := ci2;
    currentConstrainedOut := cc2;
    steps := maxSteps;
  }

  // Phase 3: No span appeared during free generation — force-open a final answer span.
  if !insideConstrainedOut && steps < maxSteps {
    var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
    generated := og;
    insideConstrainedOut := oi;
    currentConstrainedOut := oc;
    steps := steps + 1;

    if insideConstrainedOut && steps < maxSteps {
      var budget3: nat := maxSteps - steps;
      var cg3, ci3, cc3 := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, budget3
      );
      generated := cg3;
      insideConstrainedOut := ci3;
      currentConstrainedOut := cc3;
      steps := maxSteps;
    }
  }

  cost := steps;

